data class JobUi(val title: String = "", val fields: List<FieldUi> = emptyList(),
                 val banner: Banner? = null, val loading: Boolean = true)

sealed interface JobIntent { data class SetAnswer(val fieldId: String, val value: String) : JobIntent; data object Retry : JobIntent }

class JobViewModel(private val jobId: String, private val repo: JobRepo, net: NetworkMonitor) : ViewModel() {
  val ui: StateFlow<JobUi> = combine(repo.observeJob(jobId), repo.observeFields(jobId), net.online, repo.pendingCount()) { job, fields, online, pending ->
    JobUi(
      title = job.title,
      fields = fields.map { it.toUi() },                                  // each carries its sync badge
      banner = when { !online && pending > 0 -> Banner.Offline(pending); fields.any { it.conflict } -> Banner.NeedsReview; else -> null },
      loading = false,
    )
  }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), JobUi())

  fun onIntent(i: JobIntent) = viewModelScope.launch {
    when (i) {
      is JobIntent.SetAnswer -> repo.setAnswer(jobId, i.fieldId, i.value)   // row + outbox, returns fast
      JobIntent.Retry -> repo.retryFailed(jobId)
    }
  }
}

@Composable
fun JobScreen(vm: JobViewModel) {
  val ui by vm.ui.collectAsStateWithLifecycle()                      // stops collecting in the background
  Scaffold(topBar = { TopAppBar(title = { Text(ui.title) }) }) { pad ->
    LazyColumn(contentPadding = pad) {
      ui.banner?.let { b ->
        item(key = "banner") { BannerRow(b, onRetry = { vm.onIntent(JobIntent.Retry) }) }
      }
      items(ui.fields, key = { it.id }) { field ->                      // stable keys: rows keep their state
        FieldRow(field, onChange = { v -> vm.onIntent(JobIntent.SetAnswer(field.id, v)) })
      }
