class SyncEngine(
  private val db: AppDatabase, private val api: SyncApi, private val merge: MergePolicy,
  private val cfg: SyncConfig, private val clock: Clock, private val telemetry: Telemetry,
) {
  private val lock = Mutex()

  suspend fun run(reason: Reason, budget: Duration): RunResult {
    if (cfg.killSwitch) return RunResult.Disabled
    if (!lock.tryLock()) return RunResult.AlreadyRunning          // single flight
    val span = telemetry.start("sync.run", reason)
    return try {
      val deadline = clock.now() + budget
      pushAll(deadline)
      pullAll(deadline)
      RunResult.Success(morePending = db.outbox().readyCount() > 0)
    } catch (e: AuthExpiredException) { RunResult.NeedsLogin }
      catch (e: IOException) { RunResult.Retry(backoffMs(db.meta().failedRuns())) }
      finally { span.end(); lock.unlock() }
  }

  private suspend fun pushAll(deadline: Instant) {
    while (clock.now() < deadline) {
      val batch = db.outbox().nextReady(limit = cfg.pushBatch, now = clock.now())
      if (batch.isEmpty()) return
      val res = api.push(PushRequest(cfg.deviceId, batch.map { it.toWire() }))
      db.withTransaction {
        res.results.forEach { r ->
          when (r.status) {
            Status.APPLIED, Status.DUPLICATE -> { db.outbox().delete(r.opId); db.entities().markSynced(r.entityId, r.version) }
            Status.CONFLICT -> db.entities().markConflict(r.entityId, r.serverFields)
            Status.REJECTED -> db.outbox().fail(r.opId, r.reason)       // visible to the user, never retried
          }
        }
      }
    }
  }

  private suspend fun pullAll(deadline: Instant) {
    var cursor = db.cursors().get(SCOPE_DEFAULT)
    do {
      val page = api.pull(cursor, limit = cfg.pullPage)
      if (page.gone) { rebuild(); return }                          // 410: older than tombstone TTL
      db.withTransaction {
        page.changes.forEach { applyOne(it) }
        db.cursors().set(SCOPE_DEFAULT, page.nextCursor)
      }
      cursor = page.nextCursor
    } while (page.hasMore && clock.now() < deadline)
  }
}

private suspend fun applyOne(ch: Change) {
  val local = db.entities().find(ch.id)
  when {
    ch.deleted && local?.hasPendingOps == true -> db.entities().markConflict(ch.id, deletedOnServer = true)
    ch.deleted -> db.entities().delete(ch.id)
    local == null -> db.entities().insert(ch.toEntity())
    !local.hasPendingOps -> db.entities().replace(ch.toEntity())
    else -> db.entities().replace(merge.resolve(local, ch))   // keep fields the user changed locally
  }
}

fun backoffMs(attempt: Int, baseMs: Long = 2_000, capMs: Long = 60 * 60_000): Long {
  val ceiling = min(capMs, baseMs shl min(attempt, 20))
  return Random.nextLong(0, ceiling + 1)        // spreads a million devices across the window
}

// The OS gives background work a fixed window. Stop at a safe point instead of being killed mid-write.
suspend fun SyncEngine.runWithin(reason: Reason, budget: Duration): RunResult =
  withTimeoutOrNull(budget - 2.seconds) {             // keep 2 s to commit and report
    run(reason, budget)
  } ?: RunResult.Retry(backoffMs = 0)                  // out of time: resume in the next window

private suspend fun SyncEngine.pullPage(cursor: String): String? {
  currentCoroutineContext().ensureActive()             // cancellation point between pages
  val page = api.pull(cursor, limit = cfg.pullPage)
  withContext(NonCancellable) {                        // never stop half way through a page
    db.withTransaction {
      page.changes.forEach { applyOne(it) }
      db.cursors().set(SCOPE_DEFAULT, page.nextCursor)
    }
  }
  return page.nextCursor.takeIf { page.hasMore }
}

