fun copyAndHash(src: InputStream, dst: File): String {
  val md = MessageDigest.getInstance("SHA-256")
  val buf = ByteArray(1 shl 20)                       // 1 MB buffer, constant memory
  dst.outputStream().buffered().use { out ->
    src.use { input ->
      while (true) {
        val n = input.read(buf); if (n < 0) break
        md.update(buf, 0, n); out.write(buf, 0, n)
      }
    }
  }
  return md.digest().joinToString("") { "%02x".format(it) }
}

fun planParts(size: Long, onCellular: Boolean): Plan {
  val min = 5L * 1024 * 1024                            // S3 minimum except last part
  val preferred = if (onCellular) 8L * 1024 * 1024 else 16L * 1024 * 1024
  val forLimit = ceil(size / 9_000.0).toLong()          // stay well under 10,000 parts
  val partSize = maxOf(min, preferred, forLimit)
  val count = ((size + partSize - 1) / partSize).toInt()
  return Plan(partSize, count)
}

class FileSliceBody(private val file: File, private val offset: Long, private val length: Long) : RequestBody() {
  override fun contentType() = "application/octet-stream".toMediaType()
  override fun contentLength() = length
  override fun writeTo(sink: BufferedSink) {
    RandomAccessFile(file, "r").use { raf ->
      raf.seek(offset)
      val buf = ByteArray(64 * 1024); var left = length
      while (left > 0) {
        val n = raf.read(buf, 0, minOf(buf.size.toLong(), left).toInt())
        sink.write(buf, 0, n); left -= n
      }
    }
  }
}

suspend fun uploadPart(t: Transfer, p: Part): String {
  val req = Request.Builder().url(p.url).put(FileSliceBody(t.file, (p.no - 1) * t.partSize, p.length)).build()
  client.newCall(req).await().use { res ->
    if (res.code == 403) throw UrlExpired(p.no)                // broker refreshes, then retry
    if (!res.isSuccessful) throw IOException("part " + p.no + " failed: " + res.code)
    return res.header("ETag") ?: error("missing ETag")
  }
}

fun enqueuePart(ctx: Context, transferId: String, part: Int) {
  val req = OneTimeWorkRequestBuilder<PartUploadWorker>()
    .setInputData(workDataOf("transfer" to transferId, "part" to part))
    .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).setRequiresStorageNotLow(true).build())
    .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 10, TimeUnit.SECONDS)
    .addTag("transfer:$transferId")                                   // cancel a whole transfer by tag
    .build()
  WorkManager.getInstance(ctx).enqueueUniqueWork("part:$transferId:$part", ExistingWorkPolicy.KEEP, req)
}

class PartUploadWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
  override suspend fun doWork(): Result {
    val id = inputData.getString("transfer") ?: return Result.failure()
    val no = inputData.getInt("part", -1)
    val (t, p) = transfers.load(id, no) ?: return Result.success()     // transfer was cancelled meanwhile
    if (p.etag != null) return Result.success()                        // already uploaded: safe to rerun
    setForeground(foregroundInfo(t))                                   // long upload: visible, not killed
    return try {
      transfers.recordPart(id, no, etag = uploadPart(t, p))            // durable before reporting success
      if (transfers.allPartsDone(id)) TransferTriggers.complete(applicationContext, id)
      Result.success()
    } catch (e: UrlExpired) {
      transfers.refreshUrl(id, no); Result.retry()                     // presigned URL timed out
    } catch (e: IOException) {
      if (runAttemptCount < 8) Result.retry() else Result.failure()
    }
  }
}

