object SyncTriggers {
  fun request(ctx: Context, reason: Reason, urgent: Boolean = false) {
    val req = OneTimeWorkRequestBuilder<SyncWorker>()
      .setInputData(workDataOf("reason" to reason.name))
      .setConstraints(Constraints(requiredNetworkType = NetworkType.CONNECTED))
      .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
      .apply { if (urgent) setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST) }
      .build()
    WorkManager.getInstance(ctx).enqueueUniqueWork("sync", ExistingWorkPolicy.KEEP, req)
  }
}

class SyncWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
  override suspend fun doWork(): Result {
    val reason = Reason.valueOf(inputData.getString("reason") ?: "PERIODIC")
    return when (val r = engine.run(reason, budget = 8.minutes)) {
      is RunResult.Success -> { if (r.morePending) SyncTriggers.request(applicationContext, Reason.FOLLOW_UP); Result.success() }
      is RunResult.Retry -> Result.retry()
      RunResult.NeedsLogin, RunResult.Disabled, RunResult.AlreadyRunning -> Result.success()
    }
  }
}

