// Periodic safety net: Android may batch or delay it, so it is never the only trigger.
fun schedulePeriodicSync(ctx: Context) {
  val req = PeriodicWorkRequestBuilder<SyncWorker>(15, TimeUnit.MINUTES)
    .setInputData(workDataOf("reason" to Reason.PERIODIC.name))
    .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).setRequiresBatteryNotLow(true).build())
    .build()
  WorkManager.getInstance(ctx).enqueueUniquePeriodicWork("sync-periodic", ExistingPeriodicWorkPolicy.KEEP, req)
}

// The user just left the app with unsynced edits: ask for expedited work, not a background service.
class LeaveAppTrigger(private val ctx: Context, private val outbox: OutboxDao) : DefaultLifecycleObserver {
  override fun onStop(owner: LifecycleOwner) {
    owner.lifecycleScope.launch {
      if (outbox.readyCount() > 0) SyncTriggers.request(ctx, Reason.BACKGROUNDED, urgent = true)
    }
  }
}

class App : Application() {
  override fun onCreate() {
    super.onCreate()
    schedulePeriodicSync(this)
    ProcessLifecycleOwner.get().lifecycle.addObserver(LeaveAppTrigger(this, db.outbox()))   // whole app, not one Activity
  }
}

