export async function applyOp(tx: Tx, tenant: string, user: User, op: Op): Promise<OpResult> {
  const seen = await tx.one('SELECT result FROM processed_op WHERE op_id = $1', [op.opId]);
  if (seen) return { ...seen.result, status: 'duplicate' };

  const row = await tx.one('SELECT * FROM job WHERE id = $1 AND tenant_id = $2 FOR UPDATE', [op.id, tenant]);
  authorize(user, 'write', row);
  const outcome = mergeRules[op.entity](row, op);              // field-level: applied or conflict
  if (outcome.kind === 'conflict') return saveResult(tx, op, { status: 'conflict', server: outcome.server });

  await tx.none('UPDATE job SET data = $1, version = version + 1 WHERE id = $2', [outcome.data, op.id]);
  const { seq } = await tx.one('UPDATE tenant_seq SET seq = seq + 1 WHERE tenant_id = $1 RETURNING seq', [tenant]);
  await tx.none('INSERT INTO change_log (tenant_id, seq, entity, entity_id, version, fields, acl) VALUES ($1,$2,$3,$4,$5,$6,$7)',
    [tenant, seq, op.entity, op.id, row.version + 1, outcome.changedFields, row.acl]);
  return saveResult(tx, op, { status: 'applied', seq, version: row.version + 1 });
}

type Matrix = number[][];

const matmul = (a: Matrix, b: Matrix): Matrix =>
  a.map((row) => b[0].map((_, j) => row.reduce((s, x, k) => s + x * b[k][j], 0)));
const transpose = (m: Matrix): Matrix => m[0].map((_, j) => m.map((row) => row[j]));

function softmax(row: number[]): number[] {
  const max = Math.max(...row);                       // subtract the max: exp() never overflows
  const e = row.map((x) => Math.exp(x - max));
  const sum = e.reduce((a, b) => a + b, 0);
  return e.map((x) => x / sum);
}

// One causal attention head. x: T tokens × D dims; Wq, Wk, Wv: D × d.
// Multi-head attention runs H of these with d = D / H and concatenates the outputs.
function causalAttention(x: Matrix, Wq: Matrix, Wk: Matrix, Wv: Matrix): Matrix {
  const q = matmul(x, Wq), k = matmul(x, Wk), v = matmul(x, Wv);
  const scale = Math.sqrt(q[0].length);
  const scores = matmul(q, transpose(k)).map((row, t) =>
    row.map((s, u) => (u > t ? -Infinity : s / scale)));   // no peeking at later tokens
  return matmul(scores.map(softmax), v);                     // T × d
}

// Temperature reshapes the distribution; top-p keeps the smallest set of tokens
// whose probability reaches p. Uses softmax from the attention example.
function sample(logits: number[], temperature = 0.7, topP = 0.9, rand = Math.random): number {
  const probs = softmax(logits.map((l) => l / Math.max(temperature, 1e-5)));
  const ranked = probs.map((p, i) => [p, i] as const).sort((a, b) => b[0] - a[0]);
  const keep: (readonly [number, number])[] = [];
  let mass = 0;
  for (const pair of ranked) {
    keep.push(pair);
    mass += pair[0];
    if (mass >= topP) break;                        // nucleus reached
  }
  let r = rand() * mass;                            // sample within the kept tokens only
  for (const [p, i] of keep) if ((r -= p) <= 0) return i;
  return keep[keep.length - 1][1];
}

