// Merge rankings from different retrievers (BM25, vectors, …) without calibrating their scores:
// each list contributes 1 / (k + rank) for every document it returns.
function rrf(rankings: string[][], k = 60): string[] {
  const scores = new Map<string, number>();
  for (const list of rankings) {
    list.forEach((id, i) => scores.set(id, (scores.get(id) ?? 0) + 1 / (k + i + 1)));
  }
  return [...scores].sort((a, b) => b[1] - a[1]).map(([id]) => id);
}

// results: query -> ranked document ids; labels: query -> ids a person marked relevant.
function recallAtK(results: Map<string, string[]>, labels: Map<string, Set<string>>, k = 10): number {
  let total = 0;
  for (const [query, relevant] of labels) {
    const top = (results.get(query) ?? []).slice(0, k);
    total += top.filter((id) => relevant.has(id)).length / relevant.size;
  }
  return total / labels.size;
}

// LoRA freezes W (dOut × dIn) and trains two thin matrices: W' = W + (alpha / r) · B·A,
// with B: dOut × r and A: r × dIn. Only B and A are saved, as a small adapter file.
const loraParams = (dIn: number, dOut: number, r: number) => r * (dIn + dOut);   // full: dIn × dOut

// Llama 3.1 8B: 32 layers, hidden size 4096, grouped-query attention (k and v project to 1024).
const layers = 32, hidden = 4096, kv = 1024, r = 16;
const perLayer =
  loraParams(hidden, hidden, r) +     // q_proj
  loraParams(hidden, kv, r) +         // k_proj
  loraParams(hidden, kv, r) +         // v_proj
  loraParams(hidden, hidden, r);      // o_proj
const trainable = layers * perLayer;  // 13,631,488
console.log(trainable.toLocaleString(), ((trainable / 8.03e9) * 100).toFixed(2) + "% of the weights");   // ≈ 0.17%

